code:
function moveQuoteToken(
    mapping(uint256 => Bucket) storage buckets_,
    DepositsState storage deposits_,
    PoolState calldata poolState_,
    MoveQuoteParams calldata params_
) external returns (uint256 fromBucketRedeemedLP_, uint256 toBucketLP_, uint256 movedAmount_, uint256 lup_) {
    if (params_.maxAmountToMove == 0)
        revert InvalidAmount();
    if (params_.fromIndex == params_.toIndex)
        revert MoveToSameIndex();
    if (params_.maxAmountToMove != 0 && params_.maxAmountToMove < poolState_.quoteDustLimit)
        revert DustAmountNotExceeded();
    if (params_.toIndex == 0 || params_.toIndex > MAX_FENWICK_INDEX) 
        revert InvalidIndex();

    Bucket storage toBucket = buckets_[params_.toIndex];

    MoveQuoteLocalVars memory vars;
    vars.toBucketBankruptcyTime = toBucket.bankruptcyTime;

    // cannot move in the same block when target bucket becomes insolvent
    if (vars.toBucketBankruptcyTime == block.timestamp) revert BucketBankruptcyBlock();

    Bucket storage fromBucket       = buckets_[params_.fromIndex];
    Lender storage fromBucketLender = fromBucket.lenders[msg.sender];

    vars.fromBucketPrice       = _priceAt(params_.fromIndex);
    vars.fromBucketCollateral  = fromBucket.collateral;
    vars.fromBucketLP          = fromBucket.lps;
    vars.fromBucketDepositTime = fromBucketLender.depositTime;

    vars.toBucketPrice         = _priceAt(params_.toIndex);

    if (fromBucket.bankruptcyTime < vars.fromBucketDepositTime) vars.fromBucketLenderLP = fromBucketLender.lps;

    (movedAmount_, fromBucketRedeemedLP_, vars.fromBucketRemainingDeposit) = _removeMaxDeposit(
        deposits_,
        RemoveDepositParams({
            depositConstraint: params_.maxAmountToMove,
            lpConstraint:      vars.fromBucketLenderLP,
            bucketLP:          vars.fromBucketLP,
            bucketCollateral:  vars.fromBucketCollateral,
            price:             vars.fromBucketPrice,
            index:             params_.fromIndex,
            dustLimit:         poolState_.quoteDustLimit
        })
    );

    lup_ = Deposits.getLup(deposits_, poolState_.debt);
    // apply unutilized deposit fee if quote token is moved from above the LUP to below the LUP
    if (vars.fromBucketPrice >= lup_ && vars.toBucketPrice < lup_) {
        movedAmount_ = Maths.wmul(movedAmount_, Maths.WAD - _depositFeeRate(poolState_.rate));
    }

    vars.toBucketUnscaledDeposit = Deposits.unscaledValueAt(deposits_, params_.toIndex);
    vars.toBucketScale           = Deposits.scale(deposits_, params_.toIndex);
    vars.toBucketDeposit         = Maths.wmul(vars.toBucketUnscaledDeposit, vars.toBucketScale);

    toBucketLP_ = Buckets.quoteTokensToLP(
        toBucket.collateral,
        toBucket.lps,
        vars.toBucketDeposit,
        movedAmount_,
        vars.toBucketPrice
    );

    Deposits.unscaledAdd(deposits_, params_.toIndex, Maths.wdiv(movedAmount_, vars.toBucketScale));

    vars.htp = Maths.wmul(params_.thresholdPrice, poolState_.inflator);

    // check loan book's htp against new lup, revert if move drives LUP below HTP
    if (params_.fromIndex < params_.toIndex && vars.htp > lup_) revert LUPBelowHTP();

    // update lender and bucket LP balance in from bucket
    vars.fromBucketRemainingLP = vars.fromBucketLP - fromBucketRedeemedLP_;

    // check if from bucket healthy after move quote tokens - set bankruptcy if collateral and deposit are 0 but there's still LP
    if (vars.fromBucketCollateral == 0 && vars.fromBucketRemainingDeposit == 0 && vars.fromBucketRemainingLP != 0) {
        fromBucket.lps            = 0;
        fromBucket.bankruptcyTime = block.timestamp;

        emit BucketBankruptcy(
            params_.fromIndex,
            vars.fromBucketRemainingLP
        );
    } else {
        // update lender and bucket LP balance
        fromBucketLender.lps -= fromBucketRedeemedLP_;

        fromBucket.lps = vars.fromBucketRemainingLP;
    }

    // update lender and bucket LP balance in target bucket
    Lender storage toBucketLender = toBucket.lenders[msg.sender];

    vars.toBucketDepositTime = toBucketLender.depositTime;
    if (vars.toBucketBankruptcyTime >= vars.toBucketDepositTime) {
        // bucket is bankrupt and deposit was done before bankruptcy time, reset lender lp amount
        toBucketLender.lps = toBucketLP_;

        // set deposit time of the lender's to bucket as bucket's last bankruptcy timestamp + 1 so deposit won't get invalidated
        vars.toBucketDepositTime = vars.toBucketBankruptcyTime + 1;
    } else {
        toBucketLender.lps += toBucketLP_;
    }

    // set deposit time to the greater of the lender's from bucket and the target bucket
    toBucketLender.depositTime = Maths.max(vars.fromBucketDepositTime, vars.toBucketDepositTime);

    // update bucket LP balance
    toBucket.lps += toBucketLP_;

    emit MoveQuoteToken(
        msg.sender,
        params_.fromIndex,
        params_.toIndex,
        movedAmount_,
        fromBucketRedeemedLP_,
        toBucketLP_,
        lup_
    );
}

function moveLiquidity(
    MoveLiquidityParams calldata params_
) external override mayInteract(params_.pool, params_.tokenId) nonReentrant {
    Position storage fromPosition = positions[params_.tokenId][params_.fromIndex];

    MoveLiquidityLocalVars memory vars;
    vars.depositTime = fromPosition.depositTime;

    // handle the case where owner attempts to move liquidity after they've already done so
    if (vars.depositTime == 0) revert RemovePositionFailed();

    // ensure bucketDeposit accounts for accrued interest
    IPool(params_.pool).updateInterest();

    // retrieve info of bucket from which liquidity is moved  
    (
        vars.bucketLP,
        vars.bucketCollateral,
        vars.bankruptcyTime,
        vars.bucketDeposit,
    ) = IPool(params_.pool).bucketInfo(params_.fromIndex);

    // check that bucket hasn't gone bankrupt since memorialization
    if (vars.depositTime <= vars.bankruptcyTime) revert BucketBankrupt();

    // calculate the max amount of quote tokens that can be moved, given the tracked LP
    vars.maxQuote = _lpToQuoteToken(
        vars.bucketLP,
        vars.bucketCollateral,
        vars.bucketDeposit,
        fromPosition.lps,
        vars.bucketDeposit,
        _priceAt(params_.fromIndex)
    );

    EnumerableSet.UintSet storage positionIndex = positionIndexes[params_.tokenId];

    // remove bucket index from which liquidity is moved from tracked positions
    if (!positionIndex.remove(params_.fromIndex)) revert RemovePositionFailed();

    // update bucket set at which a position has liquidity
    // slither-disable-next-line unused-return
    positionIndex.add(params_.toIndex);

    // move quote tokens in pool
    (
        vars.lpbAmountFrom,
        vars.lpbAmountTo,
    ) = IPool(params_.pool).moveQuoteToken(
        vars.maxQuote,
        params_.fromIndex,
        params_.toIndex,
        params_.expiry
    );

    Position storage toPosition = positions[params_.tokenId][params_.toIndex];

    // update position LP state
    fromPosition.lps -= vars.lpbAmountFrom;
    toPosition.lps   += vars.lpbAmountTo;
    // update position deposit time to the from bucket deposit time
    toPosition.depositTime = vars.depositTime;

    emit MoveLiquidity(
        ownerOf(params_.tokenId),
        params_.tokenId,
        params_.fromIndex,
        params_.toIndex,
        vars.lpbAmountFrom,
        vars.lpbAmountTo
    );
}

function reedemPositions(
    RedeemPositionsParams calldata params_
) external override mayInteract(params_.pool, params_.tokenId) {
    EnumerableSet.UintSet storage positionIndex = positionIndexes[params_.tokenId];

    IPool pool = IPool(params_.pool);

    uint256 indexesLength = params_.indexes.length;
    uint256[] memory lpAmounts = new uint256[](indexesLength);

    uint256 index;

    for (uint256 i = 0; i < indexesLength; ) {
        index = params_.indexes[i];

        Position memory position = positions[params_.tokenId][index];

        if (position.depositTime == 0 || position.lps == 0) revert RemovePositionFailed();

        // check that bucket didn't go bankrupt after memorialization
        if (_bucketBankruptAfterDeposit(pool, index, position.depositTime)) revert BucketBankrupt();

        // remove bucket index at which a position has added liquidity
        if (!positionIndex.remove(index)) revert RemovePositionFailed();

        lpAmounts[i] = position.lps;

        // remove LP tracked by position manager at bucket index
        delete positions[params_.tokenId][index];

        unchecked { ++i; }
    }

    address owner = ownerOf(params_.tokenId);

    // approve owner to take over the LP ownership (required for transferLP pool call)
    pool.increaseLPAllowance(owner, params_.indexes, lpAmounts);
    // update pool lps accounting and transfer ownership of lps from PositionManager contract
    pool.transferLP(address(this), owner, params_.indexes);

    emit RedeemPosition(owner, params_.tokenId, params_.indexes);
}

function _bucketBankruptAfterDeposit(
    IPool pool_,
    uint256 index_,
    uint256 depositTime_
) internal view returns (bool) {
    (, , uint256 bankruptcyTime, , ) = pool_.bucketInfo(index_);
    return depositTime_ <= bankruptcyTime;
}

