) external override {
    EnumerableSet.UintSet storage positionIndex = positionIndexes[params_.tokenId];

    IPool   pool  = IPool(poolKey[params_.tokenId]);
    address owner = ownerOf(params_.tokenId);

    uint256 indexesLength = params_.indexes.length;
    uint256 index;

    for (uint256 i = 0; i < indexesLength; ) {
        index = params_.indexes[i];

        // record bucket index at which a position has added liquidity
        // slither-disable-next-line unused-return
        positionIndex.add(index);

        (uint256 lpBalance, uint256 depositTime) = pool.lenderInfo(index, owner);

        Position memory position = positions[params_.tokenId][index];

        // check for previous deposits
        if (position.depositTime != 0) {
            // check that bucket didn't go bankrupt after prior memorialization
            if (_bucketBankruptAfterDeposit(pool, index, position.depositTime)) {
                // if bucket did go bankrupt, zero out the LP tracked by position manager
                position.lps = 0;
            }
        }

        // update token position LP
        position.lps += lpBalance;
        // set token's position deposit time to the original lender's deposit time
        position.depositTime = depositTime;

        // save position in storage
        positions[params_.tokenId][index] = position;

        unchecked { ++i; }
    }

    // update pool LP accounting and transfer ownership of LP to PositionManager contract
    pool.transferLP(owner, address(this), params_.indexes);

    emit MemorializePosition(owner, params_.tokenId, params_.indexes);
}

function stake(
    uint256 tokenId_
) external override {
    address ajnaPool = PositionManager(address(positionManager)).poolKey(tokenId_);

    // check that msg.sender is owner of tokenId
    if (IERC721(address(positionManager)).ownerOf(tokenId_) != msg.sender) revert NotOwnerOfDeposit();

    StakeInfo storage stakeInfo = stakes[tokenId_];
    stakeInfo.owner    = msg.sender;
    stakeInfo.ajnaPool = ajnaPool;

    uint256 curBurnEpoch = IPool(ajnaPool).currentBurnEpoch();

    // record the staking epoch
    stakeInfo.stakingEpoch = uint96(curBurnEpoch);

    // initialize last time interaction at staking epoch
    stakeInfo.lastClaimedEpoch = uint96(curBurnEpoch);

    uint256[] memory positionIndexes = positionManager.getPositionIndexes(tokenId_);

    for (uint256 i = 0; i < positionIndexes.length; ) {

        uint256 bucketId = positionIndexes[i];

        BucketState storage bucketState = stakeInfo.snapshot[bucketId];

        // record the number of lps in bucket at the time of staking
        bucketState.lpsAtStakeTime = uint128(positionManager.getLP(
            tokenId_,
            bucketId
        ));
        // record the bucket exchange rate at the time of staking
        bucketState.rateAtStakeTime = uint128(IPool(ajnaPool).bucketExchangeRate(bucketId));

        // iterations are bounded by array length (which is itself bounded), preventing overflow / underflow
        unchecked { ++i; }
    }

    emit Stake(msg.sender, ajnaPool, tokenId_);

    // transfer LP NFT to this contract
    IERC721(address(positionManager)).transferFrom(msg.sender, address(this), tokenId_);

    // calculate rewards for updating exchange rates, if any
    uint256 updateReward = _updateBucketExchangeRates(
        ajnaPool,
        positionIndexes
    );

    // transfer rewards to sender
    _transferAjnaRewards(updateReward);
}

function increaseLPAllowance(
    address spender_,
    uint256[] calldata indexes_,
    uint256[] calldata amounts_
) external override nonReentrant {
    LPActions.increaseLPAllowance(
        _lpAllowances[msg.sender][spender_],
        spender_,
        indexes_,
        amounts_
    );
}

function transferLP(
    mapping(uint256 => Bucket) storage buckets_,
    mapping(address => mapping(address => mapping(uint256 => uint256))) storage allowances_,
    mapping(address => mapping(address => bool)) storage approvedTransferors_,
    address ownerAddress_,
    address newOwnerAddress_,
    uint256[] calldata indexes_
) external {
    // revert if msg.sender is not the new owner and is not approved as a transferor by the new owner
    if (newOwnerAddress_ != msg.sender && !approvedTransferors_[newOwnerAddress_][msg.sender]) revert TransferorNotApproved();

    // revert if new owner address is the same as old owner address
    if (ownerAddress_ == newOwnerAddress_) revert TransferToSameOwner();

    uint256 indexesLength = indexes_.length;
    uint256 index;
    uint256 lpTransferred;

    for (uint256 i = 0; i < indexesLength; ) {
        index = indexes_[i];

        // revert if invalid index
        if (index > MAX_FENWICK_INDEX) revert InvalidIndex();

        Bucket storage bucket = buckets_[index];
        Lender storage owner  = bucket.lenders[ownerAddress_];

        uint256 bankruptcyTime   = bucket.bankruptcyTime;
        uint256 ownerDepositTime = owner.depositTime;
        uint256 ownerLpBalance   = bankruptcyTime < ownerDepositTime ? owner.lps : 0;

        uint256 allowedAmount = allowances_[ownerAddress_][newOwnerAddress_][index];
        if (allowedAmount == 0) revert NoAllowance();

        // transfer allowed amount or entire LP balance
        allowedAmount = Maths.min(allowedAmount, ownerLpBalance);

        // move owner LP (if any) to the new owner
        if (allowedAmount != 0) {
            Lender storage newOwner = bucket.lenders[newOwnerAddress_];

            uint256 newOwnerDepositTime = newOwner.depositTime;

            if (newOwnerDepositTime > bankruptcyTime) {
                // deposit happened in a healthy bucket, add amount of LP to new owner
                newOwner.lps += allowedAmount;
            } else {
                // bucket bankruptcy happened after deposit, reset balance and add amount of LP to new owner
                newOwner.lps = allowedAmount;
            }

            owner.lps     -= allowedAmount; // remove amount of LP from old owner
            lpTransferred += allowedAmount; // add amount of LP to total LP transferred

            // set the deposit time as the max of transferred deposit and current deposit time
            newOwner.depositTime = Maths.max(ownerDepositTime, newOwnerDepositTime);
        }

        // reset allowances of transferred LP
        delete allowances_[ownerAddress_][newOwnerAddress_][index];

        unchecked { ++i; }
    }

    emit TransferLP(
        ownerAddress_,
        newOwnerAddress_,
        indexes_,
        lpTransferred
    );
}

function mint(
    MintParams calldata params_
) external override nonReentrant returns (uint256 tokenId_) {
    tokenId_ = _nextId++;

    // revert if the address is not a valid Ajna pool
    if (!_isAjnaPool(params_.pool, params_.poolSubsetHash)) revert NotAjnaPool();

    // record which pool the tokenId was minted in
    poolKey[tokenId_] = params_.pool;

    _mint(params_.recipient, tokenId_);

    emit Mint(params_.recipient, params_.pool, tokenId_);
}

